const params=new URLSearchParams(location.search);let current=params.get('screen')||'S01',device=params.get('device')||'mobile',history=[],dirty=false,menuFilter='',chatMessages=[],currentRole='student',lastFocus=null;
if(!byId[current])current='S01';if(!['mobile','tablet','desktop'].includes(device))device='mobile';if(params.get('clean')==='1')document.body.classList.add('clean');
const app=document.getElementById('app'),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function icon(n,size=20){return (ICONS[n]||ICONS.CircleHelp).replace('width="24"',`width="${size}"`).replace('height="24"',`height="${size}"`).replace('stroke="#161616"','stroke="currentColor"')}
function ib(n,label,go='',action=''){return `<button type="button" class="icon-button" aria-label="${esc(label)}" title="${esc(label)}" ${go?`data-go="${go}"`:''} ${action?`data-action="${action}"`:''}>${icon(n)}</button>`}
function btn(label,go='',style='',action=''){return `<button type="button" class="btn ${style}" ${go?`data-go="${go}"`:''} ${action?`data-action="${action}"`:''}>${esc(label)}</button>`}
function av(letter='س',style='',size=44){return `<div class="avatar ${style}" style="width:${size}px;height:${size}px">${esc(letter)}</div>`}
function badge(label,type=''){return `<span class="badge ${type}">${esc(label)}</span>`}
function notice(str,type='',ico='Info'){return `<div class="notice ${type}">${icon(ico,20)}<span>${esc(str)}</span></div>`}
function row(title,meta,letter='م',go='',extra='',type=''){return `<button type="button" class="list-row" ${go?`data-go="${go}"`:`data-action="details"`} aria-label="${esc(title)}">${av(letter,type)}<span class="grow"><span class="label">${esc(title)}</span><span class="meta">${esc(meta)}</span></span>${extra||`<span class="chevron">${icon('ChevronLeft',18)}</span>`}</button>`}
function section(title,more='',go=''){return `<div class="section-heading"><h3>${esc(title)}</h3>${more?btn(more,go,'text'):''}</div>`}
function search(label){return `<div class="search">${icon('Search',20)}<input class="filter-input" aria-label="${esc(label)}" placeholder="${esc(label)}"></div>`}
function tabs(labels,active=0){return `<div class="tabs" role="tablist">${labels.map((x,i)=>`<button type="button" role="tab" aria-selected="${i===active}" class="tab ${i===active?'active':''}" data-action="tab">${esc(x)}</button>`).join('')}</div>`}
function cover(title='معادله‌های<br>خطی',caption='فصل سوم · ریاضی نهم'){return `<div class="course-cover"><div class="cover-orbit" aria-hidden="true"></div><div class="copy"><span class="chapter-tag">${caption}</span><h2>${title}</h2><span class="cover-footnote">یک مسئله، یک نگاه تازه</span></div><div class="art" aria-hidden="true"><span class="math-tile">x²</span><span class="formula">2x + 3 = 11</span><span class="orbit-dot"></span></div></div>`}
function metrics(arr){return `<div class="metrics">${arr.map(([n,t])=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div>`}
function shortcuts(){return `<div class="shortcuts">${[['x²','ریاضی','','S03'],['EN','زبان','amber','S02'],['ع','علوم','green','S02'],['+','همه کلاس‌ها','','S02']].map(([x,t,c,g])=>`<button type="button" class="shortcut" data-go="${g}">${av(x,c,48)}<span>${t}</span></button>`).join('')}</div>`}
function screenRole(s){return s.role==='platform-admin'?'platform':['student','teacher','manager','parent','platform','personal'].includes(s.role)?s.role:null}
function getRole(s){return screenRole(s)||currentRole}
function isPublicScreen(s){return /^A0[1-6]$/.test(s.id)||['W01','W02'].includes(s.id)}
function homeRoute(s){return ({teacher:'T01',manager:'M01',parent:'P01',platform:'B01',personal:'A07'})[getRole(s)]||'S01'}
function ownName(s){return getRole(s)==='teacher'?'مریم رضایی':getRole(s)==='manager'?'امید رضایی':'سارا احمدی'}
function topbar(s){if(isPublicScreen(s))return `<div class="topbar">${['A01','W01'].includes(s.id)?'':ib('ChevronRight','بازگشت','','back')}<h2 class="${['A01','W01'].includes(s.id)?'brand-word':''}">${['A01','W01'].includes(s.id)?'ماکان':esc(s.title)}</h2>${s.module==='marketing'?btn('ورود','A01','text'):''}</div>`;return `<div class="topbar">${s.kind==='home'?ib('ChevronDown','انتخاب فضای کار','','workspace'):ib('ChevronRight','بازگشت','','back')}<h2 class="${s.id==='S01'?'brand-word':''}">${s.id==='S01'?'ماکان':esc(s.title)}</h2><div class="actions">${s.module==='messenger'?ib('SquarePen','پیام جدید','C02')+ib('Search','جستجوی پیام','C13'):ib('Search','جستجو','','searchFocus')+ib('Bell','اعلان‌ها','U10')}</div></div>`}
function nav(s){const role=getRole(s),home=homeRoute(s),active=s.module==='messenger'?'C01':s.module==='profile'?'U01':home;const items=s.module==='platform'?[['House','عملیات','B01'],['Building2','آموزشگاه‌ها','B02'],['UsersRound','کاربران','B05'],['ShieldCheck','گزارش‌ها','B06'],['Wallet','پلن‌ها','B08'],['ClipboardList','رویدادها','B11']]:role==='personal'?[['House','خانه','A07'],['MessageCircle','پیام‌ها','C01'],['UsersRound','مخاطبان','U07'],['Bookmark','ذخیره‌شده‌ها','C14'],['UserRound','پروفایل','U01']]:[['House','آموزشگاه',home],['BookOpen','کلاس‌ها','S02'],['MessageCircle','پیام‌ها','C01'],['CalendarDays','برنامه','S05'],['Bookmark','ذخیره‌شده‌ها','C14'],['UserRound','پروفایل','U01']];return `<aside class="appnav"><div class="brand">${icon('BookOpen',28)}<span>ماکان</span></div><button type="button" class="workspace" data-action="workspace"><div class="grow"><strong>${s.module==='platform'?'مدیریت پلتفرم':role==='personal'?'فضای شخصی':'آموزشگاه آفتاب'}</strong><small>${({student:'دانش‌آموز',teacher:'معلم',manager:'مدیر آموزشگاه',parent:'والد',platform:'ادمین',personal:'حساب شخصی'}[role])||'حساب من'}</small></div>${icon('ChevronDown',16)}</button>${items.map(([i,t,g])=>`<button type="button" class="navitem ${g===active||g===current?'active':''}" data-go="${g}">${icon(i)}<span>${t}</span></button>`).join('')}<div class="navbottom"><button type="button" class="navitem" data-go="U04">${icon('Settings')}<span>تنظیمات</span></button><div class="userchip">${av(ownName(s)[0],'',40)}<div class="grow"><strong>${ownName(s)}</strong><small>حساب من</small></div></div></div></aside>`}
function bottom(s){const home=homeRoute(s),role=getRole(s);let items=role==='platform'?[['House','مدیریت',home],['ShieldCheck','گزارش‌ها','B06'],['UserRound','پروفایل','U01']]:[['House',role==='personal'?'خانه':role==='parent'?'فرزندان':'خانه',home],['MessageCircle','پیام‌ها','C01'],['UserRound','پروفایل','U01']];if(device==='tablet'){items=({student:[['House','خانه',home],['BookOpen','کلاس‌ها','S02'],['MessageCircle','پیام‌ها','C01'],['CalendarDays','برنامه','S05'],['UserRound','پروفایل','U01']],teacher:[['House','خانه',home],['ClipboardList','ارزیابی','T07'],['MessageCircle','پیام‌ها','C01'],['UserRound','پروفایل','U01']],manager:[['House','خانه',home],['UsersRound','افراد','M02'],['BookOpen','درس‌ها','M08'],['MessageCircle','پیام‌ها','C01'],['UserRound','پروفایل','U01']],parent:[['House','فرزندان',home],['ChartNoAxesCombined','پیشرفت','P03'],['MessageCircle','پیام‌ها','C01'],['UserRound','پروفایل','U01']],personal:[['House','خانه',home],['MessageCircle','پیام‌ها','C01'],['UsersRound','مخاطبان','U07'],['Bookmark','ذخیره‌ها','C14'],['UserRound','پروفایل','U01']],platform:[['House','مدیریت',home],['Building2','آموزشگاه‌ها','B02'],['UsersRound','کاربران','B05'],['ShieldCheck','گزارش‌ها','B06'],['UserRound','پروفایل','U01']]})[role]||items;}let active=items.some(x=>x[2]===current)?current:s.module==='messenger'?'C01':s.module==='profile'?'U01':home;if(device==='tablet'&&role==='student'&&s.module==='learning'&&!['S01','S05'].includes(current))active='S02';return `<nav class="bottomnav" aria-label="ناوبری اصلی">${items.map(([i,t,g])=>`<button type="button" data-go="${g}" ${g===active?'aria-current="page"':''} class="${g===active?'active':''}"><span class="nav-glyph">${icon(i,22)}</span><span>${t}</span></button>`).join('')}</nav>`}
function context(s){return `<aside class="context"><div class="row">${av(ownName(s)[0],'',48)}<div class="grow"><h3>${ownName(s)}</h3><p class="caption muted">آموزشگاه آفتاب</p></div>${btn('تغییر','','text','workspace')}</div><div class="divider"></div><p class="heading">${s.kind==='form'?'راهنمای این صفحه':'برنامهٔ پیش رو'}</p>${s.kind==='form'?`<p class="note">${/ویرایش|اصلاح/.test(s.title)?'جزئیاتی را که لازم است تغییر دهید و سپس تغییرات را ذخیره کنید.':'اطلاعات را مرحله‌به‌مرحله وارد کنید و پیش از ثبت، آن‌ها را مرور کنید.'}</p><div class="notice">${icon('ShieldCheck',20)}<span>حریم خصوصی و دسترسی‌ها در هر نقش حفظ می‌شود.</span></div>`:`${row('ریاضی نهم','پنجشنبه · ۱۶:۳۰','ر','S06')}${row('زبان انگلیسی','پنجشنبه · ۱۸:۰۰','ز','S06')}${btn('مشاهده برنامه','S05','text')}`}<div class="divider"></div><p class="caption muted">راهنما · حریم خصوصی · شرایط استفاده</p><p class="caption muted">ماکان — یادگیری، کنار هم</p></aside>`}
function primary(s){return btn(s.primaryCTA,'','full','primary')}
function home(s){if(s.id==='S01')return `<div class="welcome-line"><div><p class="eyebrow">پنجشنبه، ۷ آبان</p><h1>سلام سارا<span class="greeting-dot" aria-hidden="true"></span></h1><p class="small muted">امروز، یک قدم تازه برای یادگیری.</p></div><button type="button" class="welcome-person" data-go="U01" aria-label="پروفایل سارا">${av('س','',44)}</button></div><div class="class-strip"><span class="eyebrow">کلاس‌های من</span>${shortcuts()}</div><div class="home-grid"><article class="lesson-card"><div class="lesson-author"><div class="row">${av('م','',34)}<div><h3>مریم رضایی</h3><p class="caption muted">ریاضی نهم · جلسهٔ امروز</p></div></div>${ib('Ellipsis','گزینه‌های بیشتر','','more')}</div>${cover()}<div class="lesson-footer"><div class="lesson-time">${icon('Clock',18)}<div><strong>۱۶:۳۰ تا ۱۷:۳۰</strong><span>پنجشنبه، ۷ آبان</span></div></div>${btn('ورود به کلاس','S06')}</div></article><div class="next-up">${section('قدم بعدی','همه','S07')}<div class="task-card"><div class="row spread"><span class="task-symbol">${icon('ClipboardList',20)}</span>${badge('تا فردا','amber')}</div><h3>تمرین فصل سوم</h3><p class="caption muted">حل معادله‌های یک‌مجهولی</p><div class="task-footer"><span class="caption muted">نمرهٔ کل ۳۰</span>${btn('شروع پاسخ','S08','text')}</div></div><div class="week-note"><span class="week-dot" aria-hidden="true"></span><div><strong>برنامهٔ هفتهٔ آینده</strong><p>زمان کلاس‌ها و یادآوری‌ها</p></div>${ib('ChevronLeft','دیدن برنامه','S05')}</div></div></div>`;
 if(s.id==='T01')return `<p class="body muted">${esc(s.subtitle)}</p>${metrics([['۳','کلاس امروز'],['۷','پاسخ تازه'],['۲','پیش‌نویس']])}<div class="divider"></div>${shortcuts()}${section('منتظر اقدام شما')}${row('پاسخ‌های ریاضی نهم','۷ پاسخ آمادهٔ بررسی','ر','T07')}${row('آزمون پایان فصل','پیش‌نویس · ۵ سؤال','آ','T21')}${row('درس معادله‌های خطی','آمادهٔ بازبینی و انتشار','د','T04')}${section('چه چیزی می‌سازید؟')}<div class="row">${btn('درس','T02','secondary grow')}${btn('تکلیف','T05','secondary grow')}${btn('آزمون','T10','secondary grow')}</div>`;
 if(s.module==='guardian')return `<p class="body muted">${esc(s.subtitle)}</p><div class="profile-head">${av('س','',88)}<div><h1>سارا احمدی</h1><p class="small muted">دانش‌آموز · پایه نهم</p></div></div>${metrics([['۱۲','حضور ثبت‌شده'],['۲','تکلیف پیش رو'],['۱','ثبت‌نشده']])}${notice('اطلاعات آموزشیِ منتشرشدهٔ سارا را اینجا دنبال کنید.','','ShieldCheck')}${section('آخرین فعالیت‌ها')}${row('تمرین فصل سوم','بازخورد تازهٔ معلم','ر','P03')}${row('جلسه بعدی','پنجشنبه · ۱۶:۳۰','ز','P03')}`;
 if(s.id==='A07')return `<div class="empty">${av('س','',88)}<h1>فضای شخصی شما</h1><p>گفتگوها، مخاطبان و چیزهایی که برایتان مهم‌اند، کنار هم.</p></div>${row('پیام‌ها','ارتباط با مخاطبان شما','پ','C01')}${row('ذخیره‌شده‌ها','پیام‌های ذخیره‌شدهٔ شما','ذ','C14')}${row('پروفایل و تنظیمات','حساب و ترجیحات شخصی','س','U01')}`;
 return `<p class="body muted">${esc(s.subtitle)}</p>${metrics(s.module==='platform'?[['۱۲۴','آموزشگاه'],['۸','درخواست تازه'],['۳','نیاز به بررسی']]:[['۲۴۸','دانش‌آموز'],['۱۸','معلم'],['۲۶','کلاس فعال']])}<div class="divider"></div>${section(s.module==='platform'?'عملیات امروز':'مدیریت آموزشگاه')}${s.content.map((c,i)=>row(c,i===0?'نیاز به بررسی':'به‌روزشده امروز',['آ','ا','ک','گ'][i%4],s.module==='platform'?['B02','B06','B10','B11'][i%4]:['M02','M05','M08','M10'][i%4])).join('')}`}
function field(f,i){const id='f-'+current+'-'+i,v=f.value??'',required=!/اختیاری/.test(f.label),help=required?'':'اختیاری';if(f.type==='toggle')return `<div class="switch-row"><span class="small">${esc(f.label)}</span><button type="button" class="switch" role="switch" aria-label="${esc(f.label)}" aria-checked="${!/خیر|false|غیرفعال/.test(String(v))}" data-action="toggle"></button></div>`;if(['file','image'].includes(f.type))return `<div class="field"><label for="${id}">${esc(f.label)}</label><div class="upload">${icon(f.type==='image'?'Image':'Upload',28)}<b class="small blue">${f.type==='image'?'انتخاب عکس از دستگاه':'افزودن فایل'}</b><span class="caption muted">${f.type==='image'?'تصویر JPG یا PNG':'برای انتخاب فایل از دستگاه، این بخش را لمس کنید.'}</span><input type="file" id="${id}" ${f.type==='image'?'accept="image/jpeg,image/png"':''} aria-label="${esc(f.label)}"><span class="upload-status" aria-live="polite">هنوز فایلی انتخاب نشده</span></div></div>`;
 if(['options','items','people','checkboxes','conversations'].includes(f.type)){let options=Array.isArray(v)?v:typeof v==='string'?v.split(/[،\n]/).filter(Boolean):[];if(!options.length)options=['گزینه اول','گزینه دوم'];return `<div class="field"><label>${esc(f.label)}</label><div class="stack options" style="gap:8px">${options.map((t,j)=>{if(typeof t==='object')t=t.text||t.title||t.label||'گزینه '+(j+1);return `<label class="option-row"><input type="${f.type==='options'?'radio':'checkbox'}" name="${id}" ${j===0?'checked':''}><span class="small grow">${esc(t)}</span></label>`}).join('')}</div>${btn(f.type==='people'?'انتخاب عضو':'افزودن مورد','','text','addOption')}</div>`}
 if(f.type==='textarea')return `<div class="field"><label for="${id}">${esc(f.label)}</label><textarea id="${id}" name="${esc(f.name)}" placeholder="توضیح خود را بنویسید…">${esc(v)}</textarea></div>`;
 if(f.type==='select'){let val=String(v||'انتخاب کنید');return `<div class="field"><label for="${id}">${esc(f.label)}</label><select id="${id}" name="${esc(f.name)}"><option>${esc(val)}</option><option>${/کلاس/.test(f.label)?'زبان انگلیسی':/ترم/.test(f.label)?'بهار ۱۴۰۶':/نوع/.test(f.label)?'تشریحی':'گزینه دیگر'}</option></select></div>`}
 let type=['tel','url'].includes(f.type)?f.type:'text',ph=v||(['date','datetime'].includes(f.type)?'انتخاب تاریخ و زمان':f.type==='otp'?'کد پیامک‌شده':f.label+' را بنویسید');return `<div class="field"><label for="${id}">${esc(f.label)}</label><input id="${id}" name="${esc(f.name)}" type="${type}" value="${esc(v)}" placeholder="${esc(ph)}" ${['otp','number','tel'].includes(f.type)?'inputmode="numeric"':''} ${['tel','url','otp'].includes(f.type)||f.name==='username'?'dir="ltr"':''} ${f.type==='otp'?'autocomplete="one-time-code"':''}><span class="help">${help}</span></div>`}
function form(s){return `${/ویرایش|اصلاح/.test(s.title)?notice('در حال ویرایش اطلاعات ثبت‌شده هستید.','','SquarePen'):''}${s.id==='M07'?notice('شماره همراه یا نام کاربری والد را وارد کنید؛ انتخاب یکی کافی است.'):''}${['T08','T22','T25'].includes(s.id)?notice('یادداشت خصوصی شما برای دانش‌آموز و والد نمایش داده نمی‌شود.','','LockKeyhole'):''}${s.content.length?`<p class="small muted">${esc(s.content[0])}</p>`:''}<form class="stack" id="screen-form" novalidate>${s.fields.map(field).join('')}</form>${s.module==='teaching'&&/افزودن|ویرایش/.test(s.title)?'<p class="caption muted">انتشار محتوا در صفحهٔ بازبینی انجام می‌شود.</p>':''}`}
function auth(s){return `<div class="auth-brand">${icon('BookOpen',56)}<strong>ماکان</strong></div><h1>${esc(s.title)}</h1><p class="body muted">${esc(s.subtitle)}</p><div class="blank"></div><form id="screen-form" class="stack">${s.fields.map(field).join('')}</form>${s.id==='A02'?btn('ویرایش شماره همراه','A01','text')+'<p class="caption muted">ارسال دوباره پس از پایان زمان انتظار</p>':'<p class="caption muted">با ادامه، شرایط استفاده و حریم خصوصی ماکان را می‌پذیرید.</p>'}`}
const conversations=[['مریم رضایی','تمرین امروز را دیدم، عالی بود.','م','C03','۱۶:۱۲'],['ریاضی نهم','علی: جزوهٔ جلسه را فرستادم.','ر','C04','۱۵:۵۴'],['آموزشگاه آفتاب','برنامهٔ هفتهٔ آینده منتشر شد.','آ','C05','۱۴:۲۱'],['زبان انگلیسی','تمرین مکالمه برای فردا','ز','C04','دیروز'],['نگار محمدی','ممنون، تا فردا!','ن','C03','دیروز'],['ذخیره‌شده‌ها','جزوه فصل سوم.pdf','ذ','C14','دوشنبه']];
function inbox(){return `${search('جستجو در پیام‌ها')}${tabs(['همه','شخصی','گروه‌ها','کانال‌ها'])}<div class="inbox-list">${conversations.map(([t,m,a,g,time],i)=>row(t,m,a,g,`<div style="align-self:center;text-align:center;min-width:34px"><span class="caption muted">${time}</span>${i<2?'<span class="unread" style="display:block;margin:8px auto"></span>':''}</div>`)).join('')}</div>`}
function calendar(){return `<div class="week">${[['دوشنبه','۴'],['سه‌شنبه','۵'],['چهارشنبه','۶'],['پنجشنبه','۷'],['جمعه','۸']].map(([t,d])=>`<button type="button" class="day ${d==='۷'?'active':''}" data-action="day"><span>${t}</span><strong>${d}</strong></button>`).join('')}</div>${section('پنجشنبه، ۷ آبان')}${row('ریاضی نهم','۱۶:۳۰ تا ۱۷:۳۰ · مریم رضایی','ر','S06')}${row('زبان انگلیسی','۱۸:۰۰ تا ۱۹:۰۰ · علی امیری','ز','S06')}${notice('زمان‌ها براساس منطقهٔ زمانی تهران نمایش داده می‌شوند.')}`}
function list(s){if(s.id==='C01')return inbox();if(s.id==='S05')return calendar();if(s.id==='E05')return `<div class="empty"><div class="avatar" style="width:96px;height:96px">${icon('Folder',48)}</div><h1>${esc(s.title)}</h1><p>با اولین فعالیت، موارد شما اینجا نمایش داده می‌شوند.</p></div>`;if(s.id==='T17')return `${notice('برای هر دانش‌آموز وضعیت را مشخص کنید.')}<div class="stack">${['سارا احمدی','علی رحیمی','نگار محمدی','رضا محمدی'].map((t,i)=>`<div class="card"><h3>${t}</h3>${tabs(['حاضر','غایب','با تأخیر'],i===2?-1:i===3?1:0)}${i===2?'<p class="caption" style="color:var(--amber)">هنوز ثبت نشده</p>':''}</div>`).join('')}</div>`;
 if(s.id==='S02')return `${search('جستجوی کلاس')}${tabs(['فعال','آرشیو'])}<div class="card">${row('ریاضی نهم','مریم رضایی','ر','S03')}${cover()}${btn('مشاهده کلاس','S03','secondary full')}</div>${row('زبان انگلیسی','علی امیری','ز','S03')}${row('علوم تجربی','زهرا کریمی','ع','S03')}`;
 if(s.id==='T21')return `${section('آزمون فصل سوم','افزودن سؤال','T12')}${s.content.map((t,i)=>row(t,'پیش‌نویس · قابل ویرایش',String(i+1),'T13')).join('')}`;
 if(s.id==='C26')return `${tabs(['تصاویر','فایل‌ها','لینک‌ها'])}${row('جزوه فصل سوم.pdf','فایل · آماده دریافت','ف','','','')}${row('تمرین ریاضی.pdf','فایل · ۷ آبان','ف')}${row('راهنمای کلاس آنلاین','لینک · آموزشگاه','ل')}`;
 if(s.module==='platform'&&device!=='mobile')return `${search('جستجو در '+s.title)}<table class="table"><thead><tr><th>عنوان</th><th>آخرین تغییر</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${s.content.map((t,i)=>`<tr><td>${esc(t)}</td><td>۷ آبان ۱۴۰۵</td><td>${badge(i===1?'نیاز به بررسی':'فعال',i===1?'amber':'green')}</td><td>${btn('مشاهده',s.id==='B02'?'B04':s.id==='B06'?'B07':'B10','text')}</td></tr>`).join('')}</tbody></table>`;
 return `${s.module==='onboarding'||s.module==='guardian'?'':search('جستجو در '+s.title)}${s.id==='U06'?notice('اگر دستگاهی را نمی‌شناسید، دسترسی آن را پایان دهید.','','ShieldCheck'):''}${s.content.map((c,i)=>{const p=c.split(' · ');const g=s.id==='S07'?'S08':s.id==='S11'?'S12':s.id==='T07'?'T08':s.id==='P01'?'P02':s.id==='C02'?'U11':s.id==='M02'?'M04':s.id==='U07'?'U11':s.id==='T24'?'T25':s.id==='C27'?'C29':s.id==='W05'?'W06':s.id==='A04'?['A07','S01','P01'][i%3]:'';return row(p[0],p.slice(1).join(' · ')||(s.id==='C20'?'زمان‌بندی‌شده · هنوز ارسال نشده':s.id==='W05'?'در انتظار بررسی':s.module==='onboarding'?'انتخاب و ادامه':'برای مشاهدهٔ جزئیات'),['س','م','آ','ر','ن'][i%5],g)}).join('')}`}
function report(s){return `${metrics([['۲۸ / ۳۰','آخرین تکلیف'],['۱۲','جلسه حاضر'],['۱','ثبت‌نشده']])}<div class="divider"></div>${section('نتیجه‌های منتشرشده')}${[['معادله‌های خطی',28,30],['عبارت‌های جبری',17,20],['آزمون فصل دوم',36,40]].map(([t,n,m])=>`<div class="score-card stack"><div class="row spread"><h3>${t}</h3><span class="small">${n} از ${m}</span></div><div class="linebar"><span style="width:${n/m*100}%"></span></div></div>`).join('')}${notice(s.module==='guardian'?'نتایج منتشرشده و بازخورد قابل مشاهده برای والد نمایش داده می‌شود.':'هر نمره با سقف نمرهٔ همان فعالیت نمایش داده می‌شود.')}`}
function detail(s){if(['S16','M10','P03'].includes(s.id))return report(s);if(s.module==='states')return `<div class="empty"><div class="avatar ${s.id==='E04'?'violet':''}" style="width:96px;height:96px">${icon(s.id==='E01'?'WifiOff':s.id==='E02'?'RefreshCw':s.id==='E04'?'Sparkles':'LockKeyhole',48)}</div><h1>${esc(s.title)}</h1>${s.content.map(c=>`<p>${esc(c)}</p>`).join('')}</div>`;
 if(s.id==='S03')return `${cover()}${metrics([['۱۲','درس'],['۴','تکلیف'],['۲','آزمون']])}${tabs(['درس‌ها','تکلیف‌ها','آزمون‌ها','برنامه'])}${row('معادله‌های خطی','درس سوم · جزوه و تمرین','۳','S04')}${row('عبارت‌های جبری','درس دوم · محتوای منتشرشده','۲','S04')}${row('گفتگوی رسمی کلاس','۲۴ عضو · آموزشگاه آفتاب','ر','C04')}`;
 if(s.id==='S04')return `${cover()}<p class="body">معادله، یک تساوی است که در آن یک مقدار ناشناخته داریم. برای پیدا کردن این مقدار، دو طرف تساوی را به یک اندازه تغییر می‌دهیم.</p><div class="question-equation">2x + 3 = 11<br>2x = 8<br>x = 4</div>${row('جزوه فصل سوم.pdf','فایل آمادهٔ دریافت','ف')}`;
 if(['S10','S15'].includes(s.id))return `<div class="empty receipt"><div class="avatar" style="width:96px;height:96px">${icon('CircleCheck',48)}</div><h1>${s.id==='S10'?'پاسخ شما تحویل شد.':'آزمون شما ثبت شد.'}</h1><p>رسید ثبت با موفقیت دریافت شد.</p></div><div class="card"><h2>${s.id==='S10'?'تمرین فصل سوم':'آزمون فصل سوم'}</h2><p class="body">شماره رسید: MK–۱۴۰۵–۱۰۲۴<br>زمان ثبت: ۷ آبان ۱۴۰۵، ۱۷:۱۵<br>وضعیت: در انتظار ارزیابی</p></div>`;
 if(s.id==='S17')return `${notice('پاسخ و پیوست‌ها را پیش از تحویل نهایی مرور کنید.')}<div class="card"><h3>تمرین فصل سوم</h3><p class="body">با کم‌کردن عدد ۳ از دو طرف معادله، ۲x = ۸ به دست می‌آید. در نتیجه x برابر ۴ است.</p></div>${row('تمرین فصل سوم.pdf','پیوست آماده','ف')}${btn('ویرایش پاسخ','S09','secondary full')}<p class="caption muted">پس از تحویل، رسید ثبت را دریافت می‌کنید.</p>`;
 if(s.id==='C08')return `<div class="empty" style="padding:12px"><div class="avatar" style="width:88px;height:88px">ر</div><h1>ریاضی نهم</h1><p>۲۴ عضو · گروه آموزشی</p></div>${row('اطلاعات گروه','عنوان و توضیحات','ر','C09')}${row('اعضا و دسترسی‌ها','مدیریت اعضا','ا','C10')}${row('رسانه‌ها و فایل‌ها','تصویر، فایل و لینک','ف','C26')}${row('موضوع‌های گفتگو','بحث‌های منظم و تفکیک‌شده','م','C27')}${row('لینک دعوت','دعوت افراد جدید','ل','C12')}`;
 if(s.id==='C16')return `<h2>کدام زمان برای کلاس جبرانی بهتر است؟</h2>${[['شنبه، ساعت ۱۶',60],['یکشنبه، ساعت ۱۷',30],['دوشنبه، ساعت ۱۶',10]].map(([t,p])=>`<button type="button" class="poll-result" data-action="vote"><span class="fill" style="width:${p}%"></span><span class="row spread"><span>${t}</span><strong>${p}٪</strong></span></button>`).join('')}<p class="caption muted">۲۰ رأی · نظرسنجی باز است</p>`;
 if(s.id==='W06')return `${notice('پرداخت هنوز تأیید نشده است.','amber','Clock')}<h2>درگاه پرداخت در دسترس نیست.</h2><p class="body muted">سفارش شما محفوظ است. پس از فعال‌شدن درگاه می‌توانید دوباره ادامه دهید.</p>${row('سفارش شماره ۱۰۲۴','در انتظار پرداخت','س')}`;
 if(s.id==='M13')return `${notice('گزارش شما در حال آماده‌سازی است.','','Clock')}<div class="card"><h3>گزارش حضور ریاضی نهم</h3><p class="small muted">آبان ۱۴۰۵ · قالب CSV</p><div class="skeleton" style="width:80%"></div><div class="skeleton" style="width:55%"></div><p class="small">پس از تکمیل، امکان دریافت فایل نمایش داده می‌شود.</p></div>`;
 return `${s.content.map((c,i)=>i===0?`<div class="card"><h2>${esc(c)}</h2><p class="small muted">${esc(s.subtitle)}</p></div>`:`<div class="row" style="align-items:flex-start">${icon('Check',20)}<p class="body grow">${esc(c)}</p></div>`).join('')}${/بازبینی|انتشار/.test(s.title)?notice('پس از انتشار، مخاطبان مجاز می‌توانند این محتوا را ببینند.'):''}`}
function profile(s){if(s.id==='U11')return `<div class="empty" style="padding:10px"><div class="avatar" style="width:96px;height:96px">م</div><h1>مریم رضایی</h1><p class="ltr">maryam.rezaei</p></div>${btn('ذخیره در مخاطبان','U09','secondary full')}${row('گزارش یا مسدود کردن','مدیریت ارتباط با این مخاطب','م','C22')}`;return `<div class="profile-head">${av('س','',92)}<div class="grow"><h1>سارا احمدی</h1><p class="username">sara.ahmadi</p><p class="caption muted">دانش‌آموز · آموزشگاه آفتاب</p></div></div>${btn('ویرایش پروفایل','U02','secondary full')}<div class="divider"></div>${section('فضاهای من')}${row('آموزشگاه آفتاب','دانش‌آموز · پایه نهم','آ','A04')}${row('حساب شخصی','پیام‌ها و مخاطبان شما','س','A07')}${section('حساب و ترجیحات')}${row('حریم خصوصی','مدیریت ارتباط و نمایش اطلاعات','ح','U04')}${row('اعلان‌ها','مدیریت پیام‌ها و یادآوری‌ها','ا','U05')}${row('امنیت و دستگاه‌ها','دستگاه‌های متصل به حساب','د','U06')}${row('مخاطبان','مخاطبان و علاقه‌مندی‌ها','م','U07')}`}
function settings(s){const arr=s.id==='U04'?[['چه کسانی می‌توانند پیام بدهند؟','مخاطبان'],['نمایش شماره همراه','هیچ‌کس'],['دعوت به گروه و کانال','مخاطبان'],['نمایش آخرین بازدید','مخاطبان'],['کاربران مسدودشده','مدیریت فهرست']]:[['پیام‌های شخصی','فعال'],['گروه‌ها و کانال‌ها','فعال'],['یادآوری کلاس و تکلیف','فعال'],['اعلان‌های ضروری حساب','همیشه فعال'],['ساعت سکوت','۲۲:۰۰ تا ۰۷:۰۰']];return `${notice(s.id==='U04'?'کنترل کنید چه کسانی بتوانند با شما ارتباط بگیرند.':'اعلان‌های ضروری حساب همیشه در دسترس می‌مانند.','','ShieldCheck')}${arr.map(([t,m])=>`<div class="switch-row"><div class="grow"><h3>${t}</h3><p class="small muted">${m}</p></div>${m==='فعال'?'<button type="button" class="switch" role="switch" aria-checked="true" aria-label="'+t+'" data-action="toggle"></button>':m==='همیشه فعال'?icon('LockKeyhole',20):ib('ChevronLeft',t,'','setting')}</div>`).join('')}`}
function exam(s){if(s.id==='E03')return `${notice('آزمون روی دستگاه دیگری فعال است.','amber','ShieldCheck')}<h1>ادامه روی این دستگاه؟</h1><p class="body muted">با انتقال، امکان ویرایش پاسخ روی دستگاه قبلی پایان می‌یابد.</p>`;if(s.id==='S12')return `${badge('آمادهٔ شروع')}<h1>آزمون فصل سوم</h1>${metrics([['۳۰','دقیقه'],['۱۰','سؤال'],['۴۰','نمره کل']])}<div class="divider"></div>${s.content.map(c=>`<p class="body">${esc(c)}</p>`).join('')}${notice('پس از شروع، زمان آزمون ادامه پیدا می‌کند.','amber','Clock')}`;if(s.id==='S14')return `${notice('پیش از تحویل نهایی، پاسخ‌ها را مرور کنید.')}${['۱','۲','۳','۴','۵'].map((n,i)=>row('سؤال '+n,i===3?'بدون پاسخ':'پاسخ ثبت شده',i===3?'؟':'✓','S13')).join('')}<p class="small muted">بعد از تحویل نهایی، پاسخ‌ها قابل ویرایش نیستند.</p>`;return `<div class="row spread"><span class="small"><b>سؤال ۳ از ۱۰</b></span>${badge('۲۴:۳۵ مانده','amber')}</div>${notice('آخرین پاسخ ذخیره شد.','green','CheckCheck')}<h2>مقدار x در معادلهٔ زیر کدام است؟</h2><div class="question-equation">2x + 3 = 11</div><div class="exam-options">${['۲','۴','۶','۸'].map(n=>`<button type="button" data-action="answer" class="${n==='۴'?'active':''}">${icon(n==='۴'?'CircleCheck':'Plus',22)}<span>${n}</span></button>`).join('')}</div>${btn('مرور پاسخ‌ها','S14','text full')}`}
function marketing(s){if(s.id==='W01')return `<div class="marketing-hero stack">${badge('برای آموزشگاه، برای هر روز')}<h1>یادگیری،<br>کنار هم.</h1><p class="body muted">کلاس‌ها، تمرین‌ها و گفتگوها را در یک فضای ساده و منظم کنار هم داشته باشید.</p>${cover('آموزش را<br>نزدیک‌تر کنیم.','یک حساب · مسیرهای متفاوت')}${section('همهٔ نقش‌ها، در یک فضا')}${row('دانش‌آموز','یادگیری و تمرین، قدم‌به‌قدم','د','S01')}${row('معلم','تدریس، ارزیابی و بازخورد','م','T01')}${row('والد','همراهی با مسیر رشد','و','P01')}${row('مدیر','مدیریت منظم آموزشگاه','م','M01')}</div>`;return `<h1>${esc(s.title)}</h1><p class="body muted">${esc(s.subtitle)}</p>${s.content.map(t=>`<div class="card soft">${icon('CircleCheck',28)}<h2>${esc(t)}</h2></div>`).join('')}`}
function bubble(msg,own,time){return `<div class="message-row ${own?'own':'incoming'}"><div class="bubble"><div>${msg}</div><div class="time">${esc(time||'۱۶:۱۲')}${own?icon('CheckCheck',14):''}</div></div></div>`}
function chat(s){let name=s.id==='C03'?'مریم رضایی':s.id==='C05'?'کانال آموزشگاه':s.id==='C14'?'ذخیره‌شده‌ها':'ریاضی نهم';return `<section class="chat"><header class="chat-header">${device==='mobile'?ib('ChevronRight','بازگشت','C01'):''}${av(s.id==='C03'?'م':s.id==='C14'?'ذ':'ر','',44)}<div class="grow"><strong>${name}</strong><span>${s.id==='C03'?'معلم ریاضی':s.id==='C05'?'اطلاع‌رسانی آموزشگاه':'گفتگوی آموزشی'}</span></div>${ib('Info','اطلاعات گفتگو',s.id==='C03'?'U11':'C08')}</header><div class="messages" id="messages"><p class="caption muted center">امروز</p>${s.id==='C05'?bubble('برنامهٔ کلاس‌های هفتهٔ آینده آماده شد. لطفاً زمان کلاس خود را بررسی کنید.',false,'۱۰:۲۴')+cover('یک هفتهٔ<br>تازه','آموزشگاه آفتاب'):bubble('سلام سارا، تمرین معادله‌ها را دیدم. مسیر حل مسئله را خیلی خوب توضیح داده بودی.',false,'۱۶:۰۸')+bubble('سلام خانم رضایی، ممنونم. برای سؤال سوم یک راه حل دیگر هم پیدا کردم.',true,'۱۶:۰۹ · ارسال شد')+bubble(`<div class="message-file"><span class="file-icon">${icon('FileText',26)}</span><div><b>تمرین فصل سوم.pdf</b><p class="caption muted">فایل آمادهٔ دریافت</p></div></div>`,true,'۱۶:۰۹')+bubble('عالیه! در جلسهٔ بعدی درباره‌اش صحبت می‌کنیم.',false,'۱۶:۱۰')+bubble('حتماً، تا جلسهٔ بعد.',true,'۱۶:۱۲ · دیده شد')}${chatMessages.map(t=>bubble(esc(t),true,'همین حالا · نمونه')).join('')}</div><form class="composer" id="composer">${ib('Plus','افزودن پیوست','','attachment')}<div class="compose-input"><input id="message-input" aria-label="متن پیام" placeholder="پیام بنویسید…" autocomplete="off">${ib('Mic','پیام صوتی','','voice')}</div><button type="submit" class="icon-button blue" aria-label="ارسال پیام">${icon('Send')}</button></form></section>`}
function content(s){return ({home:home,auth:auth,form:form,list:list,detail:detail,profile:profile,settings:settings,exam:exam,marketing:marketing}[s.kind]||detail)(s)}
function render(){const s=byId[current],publicShell=isPublicScreen(s),formlike=['form','auth','exam'].includes(s.kind),hideNav=publicShell||formlike||s.kind==='conversation'||s.module==='states',split=device!=='mobile'&&(s.kind==='conversation'||s.id==='C01');document.querySelectorAll('[data-device]').forEach(b=>b.classList.toggle('active',b.dataset.device===device));document.getElementById('screen-code').textContent=current+' / '+SPECS.length;document.getElementById('screen-label').innerHTML=`<span>${esc(moduleNames[s.module])}</span><span>•</span><span>${esc(s.title)}</span>`;let stage;if(split)stage=`${topbar(s)}<div class="conversation-layout"><div class="conversation-index">${inbox()}</div>${chat(s.id==='C01'?byId.C03:s)}</div>${device==='tablet'&&!hideNav?bottom(s):''}`;else if(s.kind==='conversation')stage=chat(s);else stage=`${topbar(s)}<div class="scroll-area ${publicShell||['auth','marketing'].includes(s.kind)||s.module==='platform'?'no-context':''}"><div class="content-columns"><main class="content ${s.kind==='form'?'form-content':''} ${s.kind==='auth'?'auth-content':''}">${!['home','auth','profile','marketing'].includes(s.kind)?`<p class="${device==='mobile'?'small':'body'} muted">${esc(s.subtitle)}</p>`:''}${content(s)}${!formlike&&!['U01','S01'].includes(s.id)?primary(s):''}</main>${publicShell||['auth','marketing'].includes(s.kind)||s.module==='platform'?'':context(s)}</div></div>${formlike||s.module==='states'?`<div class="sticky-actions">${btn('بازگشت','','secondary back-action','back')}${primary(s)}</div>`:device!=='desktop'&&!hideNav?bottom(s):''}`;
 app.innerHTML=`<div class="screen ${device}" data-screen-id="${s.id}">${device==='mobile'?'<div class="status"><span>9:41</span><span class="status-icons">LTE '+icon('ChartNoAxesCombined',12)+'<span class="battery"></span></span></div>':(publicShell||device==='tablet'?'':nav(s))}<div class="stage">${stage}</div></div>`;document.getElementById('review-logo').innerHTML=icon('BookOpen',24);dirty=false;updateScale();document.querySelector('#screen-form')?.addEventListener('input',()=>dirty=true);document.querySelectorAll('.upload input[type=file]').forEach(input=>input.addEventListener('change',()=>{input.closest('.upload').querySelector('.upload-status').textContent=input.files.length?[...input.files].map(f=>f.name).join('، '):'هنوز فایلی انتخاب نشده';dirty=true;}));document.querySelector('#composer')?.addEventListener('submit',e=>{e.preventDefault();const v=document.getElementById('message-input').value.trim();if(v){chatMessages.push(v);render();document.getElementById('messages').scrollTop=99999;}});document.querySelectorAll('.filter-input').forEach(i=>i.addEventListener('input',()=>{const query=i.value.toLowerCase();const scope=i.closest('.conversation-index')||document.querySelector('.content');scope.querySelectorAll('.list-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(query));}));window.__currentScreen={id:current,device,count:SPECS.length};}
function updateScale(){if(document.body.classList.contains('clean'))return;const frame=document.querySelector('.screen');if(!frame)return;const w={mobile:390,tablet:834,desktop:1440}[device],available=Math.max(300,innerWidth-48),scale=Math.min(1,available/w);const wrap=document.querySelector('.canvas-wrap');wrap.style.zoom=scale;}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
function closeModal(){document.getElementById('overlay').classList.remove('show');document.getElementById('modal').className='modal';lastFocus?.focus();}
function modal(html,wide=false){lastFocus=document.activeElement;const m=document.getElementById('modal');m.className='modal'+(wide?' route-dialog':'');m.innerHTML=html;document.getElementById('overlay').classList.add('show');m.querySelector('button,input,select')?.focus();}
function confirmAction(title,body,yes,callback){modal(`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="buttons">${btn(yes,'','','confirm')}${btn('انصراف','','secondary','close')}</div>`);document.querySelector('[data-action="confirm"]').onclick=()=>{closeModal();callback()};}
function go(id,{force=false,replace=false}={}){if(!byId[id]){toast('این مسیر از فهرست صفحه‌ها قابل بررسی است.');return}if(dirty&&!force){confirmAction('از این صفحه خارج می‌شوید؟','تغییرات ذخیره‌نشدهٔ این فرم از دست می‌رود.','خروج از صفحه',()=>go(id,{force:true,replace}));return}if(!replace)history.push(current);current=id;currentRole=screenRole(byId[id])||currentRole;chatMessages=[];closeModal();render();document.querySelector('.scroll-area')?.scrollTo(0,0);}
